<?php if(!$items): ?><div class="cart-empty-state"><span class="cart-empty-icon">🛒</span><h2>Giỏ hàng đang trống</h2><p>Chọn sản phẩm yêu thích để bắt đầu mua sắm.</p><a class="button button-dark" href="index.php?page=sanpham">Khám phá sản phẩm</a></div>
<?php else: ?><div class="cart-page-layout"><section class="cart-items-column"><div class="cart-shipping-progress"><div class="cart-shipping-copy"><span><?=$subtotal >= $free?'Đơn hàng của bạn được miễn phí vận chuyển.':'Mua thêm <strong>'.money($free-$subtotal).'</strong> để được <strong>miễn phí vận chuyển</strong>.'?></span><span class="cart-shipping-amount"><?=$shippingFee?'Phí vận chuyển '.money($shippingFee):'Đã đạt ưu đãi vận chuyển'?></span></div><div class="cart-progress-track"><span style="width:<?=round($progress,2)?>%"></span></div></div>
